 16→	"github.com/entireio/cli/cmd/entire/cli/agent"
 17→	"github.com/entireio/cli/cmd/entire/cli/agent/types"
 18→	"github.com/entireio/cli/cmd/entire/cli/logging"
 19→	"github.com/entireio/cli/cmd/entire/cli/paths"
 20→)
 21→
 22→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 23→func init() {
 24→	agent.Register(agent.AgentNameKiro, NewKiroAgent)
 25→}
 26→
 27→// KiroAgent implements the Agent interface for Amazon's Kiro CLI.
 28→//
 29→//nolint:revive // KiroAgent is clearer than Agent in this context
 30→type KiroAgent struct{}
 31→
 32→// NewKiroAgent creates a new Kiro agent instance.
 33→func NewKiroAgent() agent.Agent {
 34→	return &KiroAgent{}
 35→}
 36→
 37→// --- Identity ---
 38→
 39→func (k *KiroAgent) Name() types.AgentName   { return agent.AgentNameKiro }
 40→func (k *KiroAgent) Type() types.AgentType   { return agent.AgentTypeKiro }
 41→func (k *KiroAgent) Description() string     { return "Kiro - Amazon AI coding CLI" }
 42→func (k *KiroAgent) IsPreview() bool         { return true }
 43→func (k *KiroAgent) ProtectedDirs() []string { return []string{".kiro"} }
 44→
 45→// DetectPresence checks if Kiro is configured in the repository.
 46→func (k *KiroAgent) DetectPresence(ctx context.Context) (bool, error) {
 47→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 48→	if err != nil {
 49→		worktreeRoot = "."
 50→	}
 51→	if _, err := os.Stat(filepath.Join(worktreeRoot, ".kiro")); err == nil {
 52→		return true, nil
 53→	}
 54→	return false, nil
 55→}
 56→
 57→// --- Transcript Storage ---
 58→
 59→// ReadTranscript reads the cached transcript JSON for a session.
 60→func (k *KiroAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 61→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from agent hook
 62→	if err != nil {
 63→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 64→	}
 65→	return data, nil
 66→}
 67→
 68→// ChunkTranscript splits a JSON transcript into chunks.
 69→// Kiro transcripts are single JSON objects; we use the JSONL chunker since the
 70→// cached format is a JSON blob that fits in a single chunk in most cases.
 71→func (k *KiroAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
 72→	if len(content) <= maxSize {
 73→		return [][]byte{content}, nil
 74→	}
 75→	// For large transcripts, split at line boundaries
 76→	chunks, err := agent.ChunkJSONL(content, maxSize)
 77→	if err != nil {
 78→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
 79→	}
 80→	return chunks, nil
 81→}
 82→
 83→// ReassembleTranscript combines transcript chunks back into a single blob.
 84→func (k *KiroAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
 85→	if len(chunks) == 1 {
 86→		return chunks[0], nil
 87→	}
 88→	return agent.ReassembleJSONL(chunks), nil
 89→}
 90→
 91→// --- Session Management ---
 92→
 93→// GetSessionID extracts the session ID from hook input.
 94→func (k *KiroAgent) GetSessionID(input *agent.HookInput) string {
 95→	return input.SessionID
 96→}
 97→
 98→// GetSessionDir returns the directory where Kiro stores session data.
 99→// For Kiro, sessions are in SQLite, but we cache transcripts to .entire/tmp/.
100→func (k *KiroAgent) GetSessionDir(repoPath string) (string, error) {
101→	return filepath.Join(repoPath, ".entire", "tmp"), nil
102→}
103→
104→// ResolveSessionFile returns the path to the cached transcript file.
105→func (k *KiroAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
106→	return filepath.Join(sessionDir, agentSessionID+".json")
107→}
108→
109→// ReadSession reads session data from the cached transcript.
110→func (k *KiroAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
111→	if input.SessionRef == "" {
112→		return nil, errors.New("session reference (transcript path) is required")
113→	}
114→
115→	data, err := os.ReadFile(input.SessionRef)
116→	if err != nil {
117→		return nil, fmt.Errorf("failed to read transcript: %w", err)
118→	}
119→
120→	return &agent.AgentSession{
121→		SessionID:  input.SessionID,
122→		AgentName:  k.Name(),
123→		SessionRef: input.SessionRef,
124→		StartTime:  time.Now(),
125→		NativeData: data,
126→	}, nil
127→}
128→
129→// WriteSession writes session data for resumption.
130→func (k *KiroAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
131→	if session == nil {
132→		return errors.New("session is nil")
133→	}
134→	if session.AgentName != "" && session.AgentName != k.Name() {
135→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, k.Name())
136→	}
137→	if session.SessionRef == "" {
138→		return errors.New("session reference (transcript path) is required")
139→	}
140→	if len(session.NativeData) == 0 {
141→		return errors.New("session has no native data to write")
142→	}
143→
144→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
145→		return fmt.Errorf("failed to create session dir: %w", err)
146→	}
147→
148→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
149→		return fmt.Errorf("failed to write transcript: %w", err)
150→	}
151→	return nil
152→}
153→
154→// FormatResumeCommand returns the command to resume a Kiro session.
155→func (k *KiroAgent) FormatResumeCommand(_ string) string {
156→	return "kiro-cli chat --resume"
157→}
158→
159→// GetHookConfigPath returns the path to the hook config file relative to repo root.
160→func (k *KiroAgent) GetHookConfigPath() string {
161→	return filepath.Join(".kiro", hooksDir, HooksFileName)
162→}
163→
164→// --- SQLite helpers ---
165→
166→// escapeSQLString escapes single quotes for use in SQLite string literals.
167→func escapeSQLString(s string) string {
168→	return strings.ReplaceAll(s, "'", "''")
169→}
170→
171→// --- SQLite session resolution ---
172→
173→// dbPath returns the path to Kiro's SQLite database.
174→func dbPath() (string, error) {
175→	home, err := os.UserHomeDir()
176→	if err != nil {
177→		return "", fmt.Errorf("failed to get home directory: %w", err)
178→	}
179→	switch runtime.GOOS {
180→	case "darwin":
181→		return filepath.Join(home, "Library", "Application Support", "kiro-cli", "data.sqlite3"), nil
182→	default: // linux
183→		return filepath.Join(home, ".local", "share", "kiro-cli", "data.sqlite3"), nil
184→	}
185→}
186→
187→// querySessionID queries the SQLite database for the most recent conversation ID
188→// associated with the given CWD.
189→func (k *KiroAgent) querySessionID(ctx context.Context, cwd string) (string, error) {
190→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
191→		return "mock-session-id", nil
192→	}
193→
194→	db, err := dbPath()
195→	if err != nil {
196→		return "", err
197→	}
198→	if _, err := os.Stat(db); err != nil {
199→		return "", fmt.Errorf("kiro database not found at %s: %w", db, err)
200→	}
201→
202→	query := fmt.Sprintf(
203→		"SELECT json_extract(value, '$.conversation_id') FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
204→		escapeSQLString(cwd),
205→	)
206→
207→	cmd := exec.CommandContext(ctx, "sqlite3", "-json", db, query)
208→	out, err := cmd.Output()
209→	if err != nil {
210→		logging.Warn(ctx, "kiro: sqlite3 query failed", "err", err, "cwd", cwd)
211→		return "", fmt.Errorf("sqlite3 query failed: %w", err)
212→	}
213→
214→	result := strings.TrimSpace(string(out))
215→	if result == "" || result == "[]" {
216→		return "", nil
217→	}
218→
219→	// sqlite3 -json returns an array of objects
220→	var rows []map[string]string
221→	if err := json.Unmarshal([]byte(result), &rows); err != nil {
222→		return "", fmt.Errorf("failed to parse sqlite3 output: %w", err)
223→	}
224→	if len(rows) == 0 {
225→		return "", nil
226→	}
227→
228→	// The column name from json_extract
229→	for _, v := range rows[0] {
230→		return v, nil
231→	}
232→	return "", nil
233→}
234→
235→// ensureCachedTranscript fetches the conversation from SQLite and caches it
236→// to .entire/tmp/<sessionID>.json. Returns the cache file path.
237→func (k *KiroAgent) ensureCachedTranscript(ctx context.Context, cwd, sessionID string) (string, error) {
238→	repoRoot, err := paths.WorktreeRoot(ctx)
239→	if err != nil {
240→		repoRoot = cwd
241→	}
242→
243→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
244→	cachePath := filepath.Join(cacheDir, sessionID+".json")
245→
246→	// Fetch fresh transcript from SQLite on every call (transcript grows during session)
247→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
248→		// In test mode, return the expected cache path without hitting SQLite.
249→		return cachePath, nil
250→	}
251→
252→	db, err := dbPath()
253→	if err != nil {
254→		return "", err
255→	}
256→
257→	query := fmt.Sprintf(
258→		"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
259→		escapeSQLString(cwd),
260→	)
261→
262→	cmd := exec.CommandContext(ctx, "sqlite3", db, query)
263→	out, err := cmd.Output()
264→	if err != nil {
265→		return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
266→	}
267→
268→	transcript := strings.TrimSpace(string(out))
269→	if transcript == "" {
270→		return "", errors.New("no transcript found")
271→	}
272→
273→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
274→		return "", fmt.Errorf("failed to create cache dir: %w", err)
275→	}
276→
277→	if err := os.WriteFile(cachePath, []byte(transcript), 0o600); err != nil {
278→		return "", fmt.Errorf("failed to write cached transcript: %w", err)
279→	}
280→
281→	return cachePath, nil
282→}
