  1→package kiro
  2→
  3→import (
  4→	"context"
  5→	"crypto/rand"
  6→	"encoding/hex"
  7→	"errors"
  8→	"io"
  9→	"os"
 10→	"path/filepath"
 11→	"strings"
 12→	"time"
 13→
 14→	"github.com/entireio/cli/cmd/entire/cli/agent"
 15→	"github.com/entireio/cli/cmd/entire/cli/logging"
 16→	"github.com/entireio/cli/cmd/entire/cli/paths"
 17→)
 18→
 19→// Kiro hook names — these become CLI subcommands under `entire hooks kiro`.
 20→// Kiro uses camelCase hook names natively, but CLI subcommands use kebab-case.
 21→const (
 22→	HookNameAgentSpawn       = "agent-spawn"
 23→	HookNameUserPromptSubmit = "user-prompt-submit"
 24→	HookNamePreToolUse       = "pre-tool-use"
 25→	HookNamePostToolUse      = "post-tool-use"
 26→	HookNameStop             = "stop"
 27→)
 28→
 29→// sessionIDFile is the filename for caching the generated session ID.
 30→// Stored in .entire/tmp/ to ensure a stable ID across all hooks in one session.
 31→const sessionIDFile = "kiro-active-session"
 32→
 33→// HookNames returns the hook verbs Kiro supports.
 34→// These become subcommands: entire hooks kiro <verb>
 35→func (k *KiroAgent) HookNames() []string {
 36→	return []string{
 37→		HookNameAgentSpawn,
 38→		HookNameUserPromptSubmit,
 39→		HookNamePreToolUse,
 40→		HookNamePostToolUse,
 41→		HookNameStop,
 42→	}
 43→}
 44→
 45→// ParseHookEvent translates a Kiro hook into a normalized lifecycle Event.
 46→// Returns nil for hooks with no lifecycle significance (preToolUse, postToolUse).
 47→func (k *KiroAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 48→	switch hookName {
 49→	case HookNameAgentSpawn:
 50→		return k.parseAgentSpawn(ctx, stdin)
 51→	case HookNameUserPromptSubmit:
 52→		return k.parseUserPromptSubmit(ctx, stdin)
 53→	case HookNameStop:
 54→		return k.parseStop(ctx, stdin)
 55→	case HookNamePreToolUse, HookNamePostToolUse:
 56→		// Pass-through hooks with no lifecycle significance
 57→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 58→	default:
 59→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 60→	}
 61→}
 62→
 63→// readHookInputOrEmpty wraps ReadAndParseHookInput, returning a zero-value
 64→// hookInputRaw on empty stdin instead of erroring. This supports the Kiro IDE
 65→// which delivers data via environment variables rather than JSON on stdin.
 66→// Malformed JSON still returns an error.
 67→func readHookInputOrEmpty(stdin io.Reader) (*hookInputRaw, error) {
 68→	raw, err := agent.ReadAndParseHookInput[hookInputRaw](stdin)
 69→	if err != nil {
 70→		if errors.Is(err, agent.ErrEmptyHookInput) {
 71→			return &hookInputRaw{}, nil
 72→		}
 73→		return nil, err
 74→	}
 75→	return raw, nil
 76→}
 77→
 78→func (k *KiroAgent) parseAgentSpawn(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
 79→	_, err := readHookInputOrEmpty(stdin)
 80→	if err != nil {
 81→		return nil, err
 82→	}
 83→
 84→	// Generate a new stable session ID and cache it for subsequent hooks.
 85→	// Kiro's SQLite transcript isn't populated until the turn ends, so we can't
 86→	// use the native conversation_id as our session ID — it would be "unknown"
 87→	// at agentSpawn/userPromptSubmit and change to the real ID at stop.
 88→	sessionID := k.generateAndCacheSessionID(ctx)
 89→
 90→	return &agent.Event{
 91→		Type:      agent.SessionStart,
 92→		SessionID: sessionID,
 93→		Timestamp: time.Now(),
 94→	}, nil
 95→}
 96→
 97→func (k *KiroAgent) parseUserPromptSubmit(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
 98→	raw, err := readHookInputOrEmpty(stdin)
 99→	if err != nil {
100→		return nil, err
101→	}
102→
103→	// IDE mode: prompt comes from USER_PROMPT env var when stdin is empty.
104→	prompt := raw.Prompt
105→	if prompt == "" {
106→		prompt = os.Getenv("USER_PROMPT")
107→	}
108→
109→	// Read the stable session ID generated at agentSpawn.
110→	sessionID := k.readCachedSessionID(ctx)
111→	if sessionID == "" {
112→		// Fallback: generate new ID if cache file is missing (e.g., agentSpawn was skipped).
113→		sessionID = k.generateAndCacheSessionID(ctx)
114→	}
115→
116→	return &agent.Event{
117→		Type:      agent.TurnStart,
118→		SessionID: sessionID,
119→		Prompt:    prompt,
120→		Timestamp: time.Now(),
121→	}, nil
122→}
123→
124→func (k *KiroAgent) parseStop(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
125→	raw, err := readHookInputOrEmpty(stdin)
126→	if err != nil {
127→		return nil, err
128→	}
129→
130→	// IDE mode: CWD may not be in stdin. Fall back to repo root.
131→	cwd := raw.CWD
132→	if cwd == "" {
133→		repoRoot, rootErr := paths.WorktreeRoot(ctx)
134→		if rootErr == nil {
135→			cwd = repoRoot
136→		}
137→	}
138→
139→	// Read the stable session ID generated at agentSpawn.
140→	sessionID := k.readCachedSessionID(ctx)
141→	if sessionID == "" {
142→		// Fallback: try SQLite for the session ID.
143→		sid, queryErr := k.querySessionID(ctx, cwd)
144→		if queryErr != nil || sid == "" {
145→			sessionID = "unknown"
146→		} else {
147→			sessionID = sid
148→		}
149→	}
150→
151→	// At stop, Kiro's SQLite transcript is available. Fetch and cache it
152→	// under our stable session ID so lifecycle.go can read it.
153→	sessionRef, _ := k.ensureCachedTranscript(ctx, cwd, sessionID) //nolint:errcheck // best-effort: fall back to placeholder
154→
155→	// IDE mode: SQLite may not exist or be at a different path. Create a
156→	// minimal placeholder transcript so the lifecycle handler can proceed
157→	// (file-diff checkpoints still work without a real transcript).
158→	if sessionRef == "" {
159→		sessionRef = k.createPlaceholderTranscript(ctx, cwd, sessionID)
160→	}
161→
162→	return &agent.Event{
163→		Type:       agent.TurnEnd,
164→		SessionID:  sessionID,
165→		SessionRef: sessionRef,
166→		Timestamp:  time.Now(),
167→	}, nil
168→}
169→
170→// createPlaceholderTranscript writes a minimal JSON transcript to .entire/tmp/
171→// so the lifecycle handler can proceed when the real transcript is unavailable
172→// (e.g., Kiro IDE mode where SQLite is at a different path).
173→func (k *KiroAgent) createPlaceholderTranscript(ctx context.Context, cwd, sessionID string) string {
174→	repoRoot, err := paths.WorktreeRoot(ctx)
175→	if err != nil {
176→		repoRoot = cwd
177→	}
178→	if repoRoot == "" {
179→		return ""
180→	}
181→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
182→	cachePath := filepath.Join(cacheDir, sessionID+".json")
183→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
184→		logging.Warn(ctx, "kiro: failed to create transcript cache dir", "err", err)
185→		return ""
186→	}
187→	if err := os.WriteFile(cachePath, []byte("{}"), 0o600); err != nil {
188→		logging.Warn(ctx, "kiro: failed to write placeholder transcript", "err", err)
189→		return ""
190→	}
191→	return cachePath
192→}
193→
194→// generateAndCacheSessionID creates a new random session ID and writes it
195→// to .entire/tmp/kiro-active-session for subsequent hooks to read.
196→func (k *KiroAgent) generateAndCacheSessionID(ctx context.Context) string {
197→	sid := generateSessionID()
198→	cachePath := k.sessionIDCachePath(ctx)
199→	if err := os.MkdirAll(filepath.Dir(cachePath), 0o750); err != nil {
200→		logging.Warn(ctx, "kiro: failed to create session ID cache dir", "err", err)
201→		return sid
202→	}
203→	if err := os.WriteFile(cachePath, []byte(sid), 0o600); err != nil {
204→		logging.Warn(ctx, "kiro: failed to write session ID cache", "err", err)
205→	}
206→	return sid
207→}
208→
209→// readCachedSessionID reads the stable session ID from .entire/tmp/kiro-active-session.
210→// Returns empty string if the cache file doesn't exist.
211→func (k *KiroAgent) readCachedSessionID(ctx context.Context) string {
212→	cachePath := k.sessionIDCachePath(ctx)
213→	data, err := os.ReadFile(cachePath) //nolint:gosec // cachePath is constructed from WorktreeRoot + constant suffix
214→	if err != nil {
215→		return ""
216→	}
217→	return strings.TrimSpace(string(data))
218→}
219→
220→// sessionIDCachePath returns the path to the session ID cache file.
221→func (k *KiroAgent) sessionIDCachePath(ctx context.Context) string {
222→	repoRoot, err := paths.WorktreeRoot(ctx)
223→	if err != nil {
224→		repoRoot = "."
225→	}
226→	return filepath.Join(repoRoot, ".entire", "tmp", sessionIDFile)
227→}
228→
229→// generateSessionID creates a random 32-character hex string for use as a session ID.
230→func generateSessionID() string {
231→	b := make([]byte, 16)
232→	if _, err := rand.Read(b); err != nil {
233→		// crypto/rand.Read never fails on supported platforms, but use timestamp fallback.
234→		return "kiro-" + time.Now().Format("20060102-150405")
235→	}
236→	return hex.EncodeToString(b)
237→}
238→

