 21→func TestNewKiroAgent(t *testing.T) {
 22→	t.Parallel()
 23→
 24→	ag := NewKiroAgent()
 25→	if ag == nil {
 26→		t.Fatal("NewKiroAgent() returned nil")
 27→	}
 28→	if _, ok := ag.(*KiroAgent); !ok {
 29→		t.Errorf("NewKiroAgent() returned type %T, want *KiroAgent", ag)
 30→	}
 31→}
 32→
 33→func TestName(t *testing.T) {
 34→	t.Parallel()
 35→
 36→	ag := &KiroAgent{}
 37→	if got := ag.Name(); got != types.AgentName("kiro") {
 38→		t.Errorf("Name() = %q, want %q", got, "kiro")
 39→	}
 40→}
