 80→func TestDetectPresence_WithoutKiroDir(t *testing.T) {
 81→	// t.Chdir prevents t.Parallel() — DetectPresence falls back to "." when
 82→	// WorktreeRoot fails (temp dir is not a git repo).
 83→	tempDir := t.TempDir()
 84→	t.Chdir(tempDir)
 85→
 86→	ag := &KiroAgent{}
 87→	found, err := ag.DetectPresence(context.Background())
 88→	if err != nil {
 89→		t.Fatalf("DetectPresence() error = %v", err)
 90→	}
 91→	if found {
 92→		t.Error("DetectPresence() = true, want false (no .kiro directory)")
 93→	}
 94→}
