  1→package geminicli
  2→
  3→import (
  4→	"encoding/json"
  5→	"fmt"
  6→	"os"
  7→	"strings"
  8→)
  9→
 10→// Transcript parsing types - Gemini CLI uses JSON format for session storage
 11→// Based on transcript_path format: ~/.gemini/tmp/<hash>/chats/session-<date>-<id>.json
 12→
 13→// Message type constants for Gemini transcripts
 14→const (
 15→	MessageTypeUser   = "user"
 16→	MessageTypeGemini = "gemini"
 17→)
 18→
 19→// GeminiTranscript represents the top-level structure of a Gemini session file
 20→type GeminiTranscript struct {
 21→	Messages []GeminiMessage `json:"messages"`
 22→}
 23→
 24→// GeminiMessage represents a single message in the transcript
 25→type GeminiMessage struct {
 26→	ID        string           `json:"id,omitempty"` // UUID for the message
 27→	Type      string           `json:"type"`         // MessageTypeUser or MessageTypeGemini
 28→	Content   string           `json:"content,omitempty"`
 29→	ToolCalls []GeminiToolCall `json:"toolCalls,omitempty"`
 30→}
 31→
 32→// UnmarshalJSON handles both string and array content formats in Gemini transcripts.
 33→// User messages use: "content": [{"text": "..."}] (array of objects)
 34→// Gemini messages use: "content": "response text" (string)
 35→func (m *GeminiMessage) UnmarshalJSON(data []byte) error {
 36→	// Use an alias to avoid infinite recursion
 37→	type Alias GeminiMessage
 38→	aux := &struct {
 39→		*Alias
 40→
 41→		Content json.RawMessage `json:"content,omitempty"`
 42→	}{
 43→		Alias: (*Alias)(m),
 44→	}
 45→
 46→	if err := json.Unmarshal(data, aux); err != nil {
 47→		return fmt.Errorf("failed to unmarshal message: %w", err)
 48→	}
 49→
 50→	if len(aux.Content) == 0 || string(aux.Content) == "null" {
 51→		m.Content = ""
 52→		return nil
 53→	}
 54→
 55→	// Try string first (most common for gemini messages)
 56→	var strContent string
 57→	if err := json.Unmarshal(aux.Content, &strContent); err == nil {
 58→		m.Content = strContent
 59→		return nil
 60→	}
 61→
 62→	// Try array of objects with "text" fields (user messages)
 63→	var parts []struct {
 64→		Text string `json:"text"`
 65→	}
 66→	if err := json.Unmarshal(aux.Content, &parts); err == nil {
 67→		var texts []string
 68→		for _, p := range parts {
 69→			if p.Text != "" {
 70→				texts = append(texts, p.Text)
 71→			}
 72→		}
 73→		m.Content = strings.Join(texts, "\n")
 74→		return nil
 75→	}
 76→
 77→	// Unknown format - leave content empty
 78→	return nil
 79→}
 80→
 81→// GeminiToolCall represents a tool call in a gemini message
 82→type GeminiToolCall struct {
 83→	ID     string                 `json:"id"`
 84→	Name   string                 `json:"name"`
 85→	Args   map[string]interface{} `json:"args"`
 86→	Status string                 `json:"status,omitempty"`
 87→}
 88→
 89→// ParseTranscript parses raw JSON content into a transcript structure
 90→func ParseTranscript(data []byte) (*GeminiTranscript, error) {
 91→	var transcript GeminiTranscript
 92→	if err := json.Unmarshal(data, &transcript); err != nil {
 93→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 94→	}
 95→	return &transcript, nil
 96→}
 97→
 98→// ExtractModifiedFiles extracts files modified by tool calls from transcript data
 99→func ExtractModifiedFiles(data []byte) ([]string, error) {
100→	transcript, err := ParseTranscript(data)
101→	if err != nil {
102→		return nil, err
103→	}
104→
105→	return ExtractModifiedFilesFromTranscript(transcript), nil
106→}
107→
108→// ExtractModifiedFilesFromTranscript extracts files from a parsed transcript
109→func ExtractModifiedFilesFromTranscript(transcript *GeminiTranscript) []string {
110→	fileSet := make(map[string]bool)
111→	var files []string
112→
113→	for _, msg := range transcript.Messages {
114→		// Only process gemini messages (assistant messages)
115→		if msg.Type != MessageTypeGemini {
116→			continue
117→		}
118→
119→		// Process tool calls in this message
120→		for _, toolCall := range msg.ToolCalls {
121→			// Check if it's a file modification tool
122→			isModifyTool := false
123→			for _, name := range FileModificationTools {
124→				if toolCall.Name == name {
125→					isModifyTool = true
126→					break
127→				}
128→			}
129→
130→			if !isModifyTool {
131→				continue
132→			}
133→
134→			// Extract file path from args map
135→			var file string
136→			if fp, ok := toolCall.Args["file_path"].(string); ok && fp != "" {
137→				file = fp
138→			} else if p, ok := toolCall.Args["path"].(string); ok && p != "" {
139→				file = p
140→			} else if fn, ok := toolCall.Args["filename"].(string); ok && fn != "" {
141→				file = fn
142→			}
143→
144→			if file != "" && !fileSet[file] {
145→				fileSet[file] = true
146→				files = append(files, file)
147→			}
148→		}
149→	}
150→
151→	return files
152→}
153→
154→// ExtractLastUserPrompt extracts the last user message from transcript data
155→func ExtractLastUserPrompt(data []byte) (string, error) {
156→	transcript, err := ParseTranscript(data)
157→	if err != nil {
158→		return "", err
159→	}
160→
161→	return ExtractLastUserPromptFromTranscript(transcript), nil
162→}
163→
164→// ExtractLastUserPromptFromTranscript extracts the last user prompt from a parsed transcript
165→func ExtractLastUserPromptFromTranscript(transcript *GeminiTranscript) string {
166→	for i := len(transcript.Messages) - 1; i >= 0; i-- {
167→		msg := transcript.Messages[i]
168→		if msg.Type != MessageTypeUser {
169→			continue
170→		}
171→
172→		// Content is now a string field
173→		if msg.Content != "" {
174→			return msg.Content
175→		}
176→	}
177→	return ""
178→}
179→
180→// ExtractAllUserPrompts extracts all user messages from transcript data
181→func ExtractAllUserPrompts(data []byte) ([]string, error) {
182→	transcript, err := ParseTranscript(data)
183→	if err != nil {
184→		return nil, err
185→	}
186→
187→	return ExtractAllUserPromptsFromTranscript(transcript), nil
188→}
189→
190→// ExtractAllUserPromptsFromTranscript extracts all user prompts from a parsed transcript
191→func ExtractAllUserPromptsFromTranscript(transcript *GeminiTranscript) []string {
192→	var prompts []string
193→	for _, msg := range transcript.Messages {
194→		if msg.Type == MessageTypeUser && msg.Content != "" {
195→			prompts = append(prompts, msg.Content)
196→		}
197→	}
198→	return prompts
199→}
200→
201→// ExtractLastAssistantMessage extracts the last gemini response from transcript data
202→func ExtractLastAssistantMessage(data []byte) (string, error) {
203→	transcript, err := ParseTranscript(data)
204→	if err != nil {
205→		return "", err
206→	}
207→
208→	return ExtractLastAssistantMessageFromTranscript(transcript), nil
209→}
210→
211→// ExtractLastAssistantMessageFromTranscript extracts the last gemini response from a parsed transcript
212→func ExtractLastAssistantMessageFromTranscript(transcript *GeminiTranscript) string {
213→	for i := len(transcript.Messages) - 1; i >= 0; i-- {
214→		msg := transcript.Messages[i]
215→		if msg.Type == MessageTypeGemini && msg.Content != "" {
216→			return msg.Content
217→		}
218→	}
219→	return ""
220→}
221→
222→// GetLastMessageID returns the ID of the last message in the transcript.
223→// Returns empty string if the transcript is empty or the last message has no ID.
224→func GetLastMessageID(data []byte) (string, error) {
225→	transcript, err := ParseTranscript(data)
226→	if err != nil {
227→		return "", err
228→	}
229→	return GetLastMessageIDFromTranscript(transcript), nil
230→}
231→
232→// GetLastMessageIDFromTranscript returns the ID of the last message in a parsed transcript.
233→// Returns empty string if the transcript is empty or the last message has no ID.
234→func GetLastMessageIDFromTranscript(transcript *GeminiTranscript) string {
235→	if len(transcript.Messages) == 0 {
236→		return ""
237→	}
238→	return transcript.Messages[len(transcript.Messages)-1].ID
239→}
240→
241→// GetLastMessageIDFromFile reads a transcript file and returns the last message's ID.
242→// Returns empty string if the file doesn't exist, is empty, or has no messages with IDs.
243→func GetLastMessageIDFromFile(path string) (string, error) {
244→	if path == "" {
245→		return "", nil
246→	}
247→
248→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
249→	if err != nil {
250→		if os.IsNotExist(err) {
251→			return "", nil
252→		}
253→		return "", fmt.Errorf("failed to read transcript: %w", err)
254→	}
255→
256→	if len(data) == 0 {
257→		return "", nil
258→	}
259→
260→	return GetLastMessageID(data)
261→}
