156→//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
157→func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
158→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
159→	logging.Info(logCtx, "turn-end",
160→		slog.String("event", event.Type.String()),
161→		slog.String("session_id", event.SessionID),
162→		slog.String("session_ref", event.SessionRef),
163→	)
164→
165→	sessionID := event.SessionID
166→	if sessionID == "" {
167→		sessionID = unknownSessionID
168→	}
169→
170→	transcriptRef := event.SessionRef
171→	if transcriptRef == "" {
172→		return errors.New("transcript file not specified")
173→	}
174→	if !fileExists(transcriptRef) {
175→		return fmt.Errorf("transcript file not found: %s", transcriptRef)
176→	}
177→
178→	// Early check: bail out quickly if the repo has no commits yet.
179→	if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
180→		logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
181→		return NewSilentError(strategy.ErrEmptyRepository)
182→	}
183→
184→	// Create session metadata directory
185→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
186→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
187→	if err != nil {
188→		sessionDirAbs = sessionDir
189→	}
190→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
191→		return fmt.Errorf("failed to create session directory: %w", err)
