194→	// If agent implements TranscriptPreparer, wait for transcript to be ready
195→	if preparer, ok := ag.(agent.TranscriptPreparer); ok {
196→		if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
197→			logging.Warn(logCtx, "failed to prepare transcript",
198→				slog.String("error", err.Error()))
199→		}
200→	}
201→
202→	// Copy transcript to session directory
203→	transcriptData, err := ag.ReadTranscript(transcriptRef)
204→	if err != nil {
205→		return fmt.Errorf("failed to read transcript: %w", err)
206→	}
207→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
208→	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
